"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[74011],{2532(e,a,o){o.r(a),o.d(a,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"cursos/solid/modulos/srp-single-responsibility/cuestionario","title":"cuestionario","description":"2. [Investigar] Dan North, creador de BDD, propuso los principios CUPID en oposici\xf3n a SOLID. \xbfC\xf3mo el principio \\"Domain-based\\" de CUPID se relaciona con SRP? \xbfPor qu\xe9 North argumenta que \\"Domain-based\\" es superior a SRP para decidir c\xf3mo dividir el c\xf3digo?","source":"@site/docs/cursos/solid/modulos/02-srp-single-responsibility/cuestionario.md","sourceDirName":"cursos/solid/modulos/02-srp-single-responsibility","slug":"/cursos/solid/modulos/srp-single-responsibility/cuestionario","permalink":"/sasf-temarios/cursos/solid/modulos/srp-single-responsibility/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/solid/modulos/srp-single-responsibility/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/solid/modulos/srp-single-responsibility/ejercicio"}}');var n=o(74848),s=o(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,l={},d=[{value:"2. [Investigar] Dan North, creador de BDD, propuso los principios CUPID en oposici\xf3n a SOLID. \xbfC\xf3mo el principio &quot;Domain-based&quot; de CUPID se relaciona con SRP? \xbfPor qu\xe9 North argumenta que &quot;Domain-based&quot; es superior a SRP para decidir c\xf3mo dividir el c\xf3digo?",id:"2-investigar-dan-north-creador-de-bdd-propuso-los-principios-cupid-en-oposici\xf3n-a-solid-c\xf3mo-el-principio-domain-based-de-cupid-se-relaciona-con-srp-por-qu\xe9-north-argumenta-que-domain-based-es-superior-a-srp-para-decidir-c\xf3mo-dividir-el-c\xf3digo",level:3},{value:"3. [Investigar] Robert C. Martin refin\xf3 su definici\xf3n de SRP en &quot;Clean Architecture&quot; (2017) respecto a la versi\xf3n original de los a\xf1os 2000. \xbfCu\xe1l fue el cambio clave y por qu\xe9 lo hizo? \xbfQu\xe9 problema pr\xe1ctico resolvi\xf3 este refinamiento?",id:"3-investigar-robert-c-martin-refin\xf3-su-definici\xf3n-de-srp-en-clean-architecture-2017-respecto-a-la-versi\xf3n-original-de-los-a\xf1os-2000-cu\xe1l-fue-el-cambio-clave-y-por-qu\xe9-lo-hizo-qu\xe9-problema-pr\xe1ctico-resolvi\xf3-este-refinamiento",level:3},{value:"4. [Investigar] \xbfC\xf3mo se relaciona SRP con los &quot;Bounded Contexts&quot; de Domain-Driven Design (Eric Evans, 2003)? \xbfPuede un Bounded Context contener m\xfaltiples clases que individualmente violen SRP pero colectivamente cumplan CCP? Explic\xe1 con un ejemplo de e-commerce.",id:"4-investigar-c\xf3mo-se-relaciona-srp-con-los-bounded-contexts-de-domain-driven-design-eric-evans-2003-puede-un-bounded-context-contener-m\xfaltiples-clases-que-individualmente-violen-srp-pero-colectivamente-cumplan-ccp-explic\xe1-con-un-ejemplo-de-e-commerce",level:3},{value:"5. [Conectar] Clase discute que SRP mejora la testabilidad. Investig\xe1 el trabajo de Michael Feathers en &quot;Working Effectively with Legacy Code&quot; (2004) sobre &quot;seams&quot; y explic\xe1 c\xf3mo SRP crea seams que habilitan pruebas unitarias en c\xf3digo que de otra forma ser\xeda intestable.",id:"5-conectar-clase-discute-que-srp-mejora-la-testabilidad-investig\xe1-el-trabajo-de-michael-feathers-en-working-effectively-with-legacy-code-2004-sobre-seams-y-explic\xe1-c\xf3mo-srp-crea-seams-que-habilitan-pruebas-unitarias-en-c\xf3digo-que-de-otra-forma-ser\xeda-intestable",level:3},{value:"6. [Conectar] La clase menciona &quot;la prueba del nombre&quot; para detectar violaciones SRP. Relacion\xe1 esto con el trabajo de Eric Evans sobre el &quot;Lenguaje Ubicuo&quot; en DDD. \xbfPor qu\xe9 un nombre vago como <code>Manager</code>, <code>Handler</code>, <code>Processor</code> es se\xf1al de violaci\xf3n SRP en ambos marcos conceptuales?",id:"6-conectar-la-clase-menciona-la-prueba-del-nombre-para-detectar-violaciones-srp-relacion\xe1-esto-con-el-trabajo-de-eric-evans-sobre-el-lenguaje-ubicuo-en-ddd-por-qu\xe9-un-nombre-vago-como-manager-handler-processor-es-se\xf1al-de-violaci\xf3n-srp-en-ambos-marcos-conceptuales",level:3},{value:"7. [Conectar] \xbfC\xf3mo se relaciona SRP con el concepto de &quot;Vertical Slice Architecture&quot; (Jimmy Bogard, 2018)? \xbfEs Vertical Slice Architecture una alternativa a SRP o una aplicaci\xf3n de SRP a nivel arquitect\xf3nico?",id:"7-conectar-c\xf3mo-se-relaciona-srp-con-el-concepto-de-vertical-slice-architecture-jimmy-bogard-2018-es-vertical-slice-architecture-una-alternativa-a-srp-o-una-aplicaci\xf3n-de-srp-a-nivel-arquitect\xf3nico",level:3},{value:"8. [Cuestionar] David Heinemeier Hansson ha argumentado que SRP destruye la cohesi\xf3n del dominio y produce modelos an\xe9micos. En Rails, un modelo <code>User</code> con validaciones, callbacks, scopes y l\xf3gica de negocio es idiom\xe1tico y productivo. \xbfEs SRP incompatible con el estilo Active Record? \xbfD\xf3nde est\xe1 el equilibrio?",id:"8-cuestionar-david-heinemeier-hansson-ha-argumentado-que-srp-destruye-la-cohesi\xf3n-del-dominio-y-produce-modelos-an\xe9micos-en-rails-un-modelo-user-con-validaciones-callbacks-scopes-y-l\xf3gica-de-negocio-es-idiom\xe1tico-y-productivo-es-srp-incompatible-con-el-estilo-active-record-d\xf3nde-est\xe1-el-equilibrio",level:3},{value:"9. [Cuestionar] \xbfPuede SRP llevar a una explosi\xf3n de clases que empeore la mantenibilidad en lugar de mejorarla? Investig\xe1 el fen\xf3meno de &quot;ravioli code&quot; (c\xf3digo ravioli: muchas clases peque\xf1as, dif\xedcil de seguir) como contraparte de &quot;spaghetti code&quot;. \xbfD\xf3nde est\xe1 el punto de equilibrio seg\xfan la literatura?",id:"9-cuestionar-puede-srp-llevar-a-una-explosi\xf3n-de-clases-que-empeore-la-mantenibilidad-en-lugar-de-mejorarla-investig\xe1-el-fen\xf3meno-de-ravioli-code-c\xf3digo-ravioli-muchas-clases-peque\xf1as-dif\xedcil-de-seguir-como-contraparte-de-spaghetti-code-d\xf3nde-est\xe1-el-punto-de-equilibrio-seg\xfan-la-literatura",level:3},{value:"10. [Cuestionar] Yegor Bugayenko en &quot;Elegant Objects&quot; (Vol. 1, 2016) argumenta que los objetos no deber\xedan tener getters ni setters, y que la verdadera encapsulaci\xf3n hace innecesario SRP. \xbfEs SRP un parche para la falta de encapsulamiento real? \xbfQu\xe9 pasar\xeda si sigui\xe9ramos los principios de Bugayenko en lugar de SOLID?",id:"10-cuestionar-yegor-bugayenko-en-elegant-objects-vol-1-2016-argumenta-que-los-objetos-no-deber\xedan-tener-getters-ni-setters-y-que-la-verdadera-encapsulaci\xf3n-hace-innecesario-srp-es-srp-un-parche-para-la-falta-de-encapsulamiento-real-qu\xe9-pasar\xeda-si-sigui\xe9ramos-los-principios-de-bugayenko-en-lugar-de-solid",level:3}];function t(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.h3,{id:"2-investigar-dan-north-creador-de-bdd-propuso-los-principios-cupid-en-oposici\xf3n-a-solid-c\xf3mo-el-principio-domain-based-de-cupid-se-relaciona-con-srp-por-qu\xe9-north-argumenta-que-domain-based-es-superior-a-srp-para-decidir-c\xf3mo-dividir-el-c\xf3digo",children:'2. [Investigar] Dan North, creador de BDD, propuso los principios CUPID en oposici\xf3n a SOLID. \xbfC\xf3mo el principio "Domain-based" de CUPID se relaciona con SRP? \xbfPor qu\xe9 North argumenta que "Domain-based" es superior a SRP para decidir c\xf3mo dividir el c\xf3digo?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': "Domain-based" propone que el c\xf3digo debe reflejar el lenguaje del dominio, no las responsabilidades t\xe9cnicas. La diferencia con SRP es sutil pero profunda: SRP divide por "raz\xf3n para cambiar" (\xbfqui\xe9n pide el cambio? = actor/stakeholder), mientras que Domain-based divide por "lenguaje ubicuo" (\xbfc\xf3mo habla el negocio de esta responsabilidad?). Ejemplo concreto de North: en un sistema de reservas, SRP producir\xeda ',(0,n.jsx)(a.code,{children:"BookingValidator"}),", ",(0,n.jsx)(a.code,{children:"BookingCalculator"}),", ",(0,n.jsx)(a.code,{children:"BookingRepository"})," (separaci\xf3n t\xe9cnica). Domain-based producir\xeda ",(0,n.jsx)(a.code,{children:"Booking"}),", ",(0,n.jsx)(a.code,{children:"PricingPolicy"}),", ",(0,n.jsx)(a.code,{children:"CancellationPolicy"})," (separaci\xf3n por concepto de dominio). North argumenta que Domain-based es superior porque: (1) el c\xf3digo es legible para el experto de dominio sin traducir conceptos de negocio a conceptos t\xe9cnicos; (2) las responsabilidades de dominio son m\xe1s estables que las t\xe9cnicas (un ",(0,n.jsx)(a.code,{children:"Booking"})," siempre ser\xe1 un Booking, pero un ",(0,n.jsx)(a.code,{children:"BookingValidator"})," puede fusionarse o dividirse seg\xfan cambios t\xe9cnicos); (3) evita la proliferaci\xf3n de clases t\xe9cnicas sin significado de negocio."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Dan North present\xf3 CUPID en 2021 en NDC. Domain-based toma inspiraci\xf3n de Domain-Driven Design (Eric Evans, 2003) donde el c\xf3digo debe hablar el lenguaje del dominio. North argumenta que SRP produce c\xf3digo "t\xe9cnicamente correcto pero sin alma de negocio".']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-robert-c-martin-refin\xf3-su-definici\xf3n-de-srp-en-clean-architecture-2017-respecto-a-la-versi\xf3n-original-de-los-a\xf1os-2000-cu\xe1l-fue-el-cambio-clave-y-por-qu\xe9-lo-hizo-qu\xe9-problema-pr\xe1ctico-resolvi\xf3-este-refinamiento",children:'3. [Investigar] Robert C. Martin refin\xf3 su definici\xf3n de SRP en "Clean Architecture" (2017) respecto a la versi\xf3n original de los a\xf1os 2000. \xbfCu\xe1l fue el cambio clave y por qu\xe9 lo hizo? \xbfQu\xe9 problema pr\xe1ctico resolvi\xf3 este refinamiento?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': El cambio clave fue pasar de "una clase debe tener una sola raz\xf3n para cambiar" (definici\xf3n 2000) a "una clase debe ser responsable ante un \xfanico actor" (Clean Architecture, 2017). La diferencia: la definici\xf3n original era circular (\xbfqu\xe9 es una "raz\xf3n"? \u2014 "algo que hace cambiar la clase" lo cual es tautol\xf3gico). El refinamiento introduce el concepto de "actor" como stakeholder organizacional (departamento, rol, equipo). Problema pr\xe1ctico resuelto: en la definici\xf3n original, dos m\xe9todos ',(0,n.jsx)(a.code,{children:"calculateTax()"})," y ",(0,n.jsx)(a.code,{children:"calculateRetirement()"})," en la misma clase ",(0,n.jsx)(a.code,{children:"EmployeeFinance"}),' podr\xedan considerarse "una sola responsabilidad" porque ambos son "c\xe1lculos financieros del empleado". Pero con la definici\xf3n refinada, ',(0,n.jsx)(a.code,{children:"calculateTax()"})," responde a Contabilidad y ",(0,n.jsx)(a.code,{children:"calculateRetirement()"}),' responde a Beneficios/RRHH \u2014 son dos actores distintos, viola SRP. El refinamiento hace SRP verificable: pregunt\xe1 "\xbfqui\xe9n pedir\xeda este cambio?" en lugar de "\xbfesto es una o dos responsabilidades?".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Martin explic\xf3 este refinamiento en Clean Architecture, Cap\xedtulo 7. La definici\xf3n original causaba debates interminables sobre qu\xe9 constituye "una responsabilidad". La definici\xf3n por actor es objetiva: identific\xe1 los stakeholders y si dos stakeholders distintos pueden pedir cambios en la misma clase, viola SRP.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-c\xf3mo-se-relaciona-srp-con-los-bounded-contexts-de-domain-driven-design-eric-evans-2003-puede-un-bounded-context-contener-m\xfaltiples-clases-que-individualmente-violen-srp-pero-colectivamente-cumplan-ccp-explic\xe1-con-un-ejemplo-de-e-commerce",children:'4. [Investigar] \xbfC\xf3mo se relaciona SRP con los "Bounded Contexts" de Domain-Driven Design (Eric Evans, 2003)? \xbfPuede un Bounded Context contener m\xfaltiples clases que individualmente violen SRP pero colectivamente cumplan CCP? Explic\xe1 con un ejemplo de e-commerce.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': SRP y Bounded Contexts operan a diferentes niveles pero comparten filosof\xeda: cada uno persigue "una raz\xf3n para cambiar" pero a distinta granularidad. Un Bounded Context es un l\xedmite conceptual donde un modelo de dominio es consistente; cada BC tiene su propio "actor" (equipo, \xe1rea de negocio). SRP aplica la misma idea a nivel de clase. Es perfectamente posible \u2014 y deseable \u2014 que un Bounded Context contenga clases que individualmente son "peque\xf1as" (cumplen SRP a nivel de clase) pero que comparten la misma raz\xf3n de cambio a nivel de contexto (cumplen CCP a nivel de paquete). Ejemplo e-commerce: Bounded Context "Pricing" contiene ',(0,n.jsx)(a.code,{children:"DiscountCalculator"}),", ",(0,n.jsx)(a.code,{children:"TaxCalculator"}),", ",(0,n.jsx)(a.code,{children:"PricingRule"}),", ",(0,n.jsx)(a.code,{children:"CurrencyConverter"}),'. Cada clase cumple SRP (una raz\xf3n para cambiar), pero todas comparten el actor "Equipo de Pricing/Finanzas" y viven en el mismo BC. CCP asegura que los cambios de Pricing no afectan al BC "Shipping" ni "Inventory". La relaci\xf3n es: Bounded Context \u2248 CCP aplicado a nivel de subsistema. SRP \u2248 CCP aplicado a nivel de clase.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Eric Evans no menciona SRP expl\xedcitamente, pero Bounded Contexts es la materializaci\xf3n de la separaci\xf3n por actores a nivel arquitect\xf3nico. Vaughn Vernon en "Implementing DDD" conecta expl\xedcitamente SRP con BCs: "un Bounded Context es el lugar donde un modelo tiene una sola raz\xf3n para cambiar".']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-clase-discute-que-srp-mejora-la-testabilidad-investig\xe1-el-trabajo-de-michael-feathers-en-working-effectively-with-legacy-code-2004-sobre-seams-y-explic\xe1-c\xf3mo-srp-crea-seams-que-habilitan-pruebas-unitarias-en-c\xf3digo-que-de-otra-forma-ser\xeda-intestable",children:'5. [Conectar] Clase discute que SRP mejora la testabilidad. Investig\xe1 el trabajo de Michael Feathers en "Working Effectively with Legacy Code" (2004) sobre "seams" y explic\xe1 c\xf3mo SRP crea seams que habilitan pruebas unitarias en c\xf3digo que de otra forma ser\xeda intestable.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Michael Feathers define "seam" como "un lugar donde se puede alterar el comportamiento sin modificar el c\xf3digo en ese lugar". SRP crea seams al separar responsabilidades en clases distintas con interfaces: cada separaci\xf3n es un punto de inyecci\xf3n donde se puede insertar un mock. Ejemplo del caso EmployeeService de la clase: antes de SRP, ',(0,n.jsx)(a.code,{children:"validarEmpleado()"})," y ",(0,n.jsx)(a.code,{children:"calcularSalarioNeto()"})," y ",(0,n.jsx)(a.code,{children:"guardarEmpleado()"})," est\xe1n en la misma clase. No hay seam para probar ",(0,n.jsx)(a.code,{children:"calcularSalarioNeto()"})," aisladamente porque est\xe1 acoplado a la validaci\xf3n y persistencia. Despu\xe9s de SRP, ",(0,n.jsx)(a.code,{children:"NominaCalculator.calcularSalarioNeto()"})," es una clase independiente con su propia interfaz \u2014 es un seam perfecto. Se puede probar pasando un ",(0,n.jsx)(a.code,{children:"Empleado"}),' mock sin BD ni validaci\xf3n. Feathers llama a esto "breaking dependencies": cada separaci\xf3n SRP es una dependencia rota que antes era monol\xedtica. La t\xe9cnica de Feathers "Extract and Override Call" es esencialmente "aplic\xe1 SRP en peque\xf1o: extra\xe9 un m\xe9todo, movelo a una nueva clase, e injectala".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Feathers y Martin convergen: SRP es simult\xe1neamente un principio de dise\xf1o y una t\xe9cnica de testabilidad. Cada responsabilidad separada es un punto de testeo aislado. Legacy code que no se puede probar es, por definici\xf3n de Feathers, c\xf3digo sin SRP."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"6-conectar-la-clase-menciona-la-prueba-del-nombre-para-detectar-violaciones-srp-relacion\xe1-esto-con-el-trabajo-de-eric-evans-sobre-el-lenguaje-ubicuo-en-ddd-por-qu\xe9-un-nombre-vago-como-manager-handler-processor-es-se\xf1al-de-violaci\xf3n-srp-en-ambos-marcos-conceptuales",children:['6. [Conectar] La clase menciona "la prueba del nombre" para detectar violaciones SRP. Relacion\xe1 esto con el trabajo de Eric Evans sobre el "Lenguaje Ubicuo" en DDD. \xbfPor qu\xe9 un nombre vago como ',(0,n.jsx)(a.code,{children:"Manager"}),", ",(0,n.jsx)(a.code,{children:"Handler"}),", ",(0,n.jsx)(a.code,{children:"Processor"})," es se\xf1al de violaci\xf3n SRP en ambos marcos conceptuales?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Eric Evans define el Lenguaje Ubicuo como un vocabulario compartido entre desarrolladores y expertos de dominio donde cada t\xe9rmino tiene un significado preciso. Una clase con nombre vago (",(0,n.jsx)(a.code,{children:"Manager"}),", ",(0,n.jsx)(a.code,{children:"Handler"}),", ",(0,n.jsx)(a.code,{children:"Processor"}),') viola el Lenguaje Ubicuo porque estos sufijos no existen en el dominio del negocio \u2014 un experto en n\xf3minas no dice "el Procesador de Empleado", dice "el c\xe1lculo de n\xf3mina" o "la validaci\xf3n de datos del empleado". La conexi\xf3n con SRP: un nombre vago es s\xedntoma de que la clase tiene m\xfaltiples responsabilidades que no se pueden nombrar con un solo t\xe9rmino del dominio. Si al intentar nombrar la clase solo se te ocurre ',(0,n.jsx)(a.code,{children:"OrderManager"}),", es porque la clase maneja validaci\xf3n, c\xe1lculo, persistencia y notificaci\xf3n \u2014 ninguna palabra del dominio abarca todas esas responsabilidades. En DDD, esto se corrige encontrando los agregados y servicios de dominio correctos; en SRP, separando responsabilidades hasta que cada clase reciba un nombre del dominio. La convergencia: ambos marcos detectan el mismo problema (mezcla de responsabilidades) con la misma se\xf1al (imposibilidad de nombrar con precisi\xf3n)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Evans y Martin, desde DDD y SOLID respectivamente, llegan a la misma heur\xedstica: el c\xf3digo bien dise\xf1ado se nombra con t\xe9rminos del negocio. Un sufijo t\xe9cnico gen\xe9rico indica que el dise\xf1o no refleja el dominio."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"7-conectar-c\xf3mo-se-relaciona-srp-con-el-concepto-de-vertical-slice-architecture-jimmy-bogard-2018-es-vertical-slice-architecture-una-alternativa-a-srp-o-una-aplicaci\xf3n-de-srp-a-nivel-arquitect\xf3nico",children:'7. [Conectar] \xbfC\xf3mo se relaciona SRP con el concepto de "Vertical Slice Architecture" (Jimmy Bogard, 2018)? \xbfEs Vertical Slice Architecture una alternativa a SRP o una aplicaci\xf3n de SRP a nivel arquitect\xf3nico?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Vertical Slice Architecture (VSA) organiza el c\xf3digo por funcionalidad de negocio (feature), no por capa t\xe9cnica. En lugar de capas horizontales (Controllers/, Services/, Repositories/), cada feature es una "rebanada vertical" (CreateOrder/, CancelOrder/, GetOrderHistory/) que contiene todo lo necesario para esa funcionalidad. La relaci\xf3n con SRP: VSA aplica SRP a nivel de m\xf3dulo/feature: cada feature es responsable ante un solo actor y cambia por una sola raz\xf3n. Es SRP a nivel arquitect\xf3nico. Contraste con la arquitectura en capas de la clase: en capas, ',(0,n.jsx)(a.code,{children:"OrderService"})," contiene l\xf3gica de crear, cancelar, y buscar \xf3rdenes \u2014 m\xfaltiples razones para cambiar (crear vs cancelar son casos de uso distintos, potencialmente con actores distintos). En VSA, ",(0,n.jsx)(a.code,{children:"CreateOrder"})," y ",(0,n.jsx)(a.code,{children:"CancelOrder"}),' son m\xf3dulos independientes, cada uno con su propio mini-controller, mini-service, mini-repository. VSA no reemplaza SRP; lo escala a nivel de m\xf3dulo. La pregunta SRP cl\xe1sica ("\xbfcu\xe1ntas razones para cambiar tiene esta clase?") se convierte en "\xbfcu\xe1ntas razones para cambiar tiene este feature folder?".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Jimmy Bogard (creador de MediatR y AutoMapper) propuso VSA como respuesta a la arquitectura en capas tradicional donde los servicios tienden a violar SRP porque agrupan casos de uso no relacionados. VSA es la aplicaci\xf3n de SRP + CQRS a nivel de estructura de proyecto."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"8-cuestionar-david-heinemeier-hansson-ha-argumentado-que-srp-destruye-la-cohesi\xf3n-del-dominio-y-produce-modelos-an\xe9micos-en-rails-un-modelo-user-con-validaciones-callbacks-scopes-y-l\xf3gica-de-negocio-es-idiom\xe1tico-y-productivo-es-srp-incompatible-con-el-estilo-active-record-d\xf3nde-est\xe1-el-equilibrio",children:["8. [Cuestionar] David Heinemeier Hansson ha argumentado que SRP destruye la cohesi\xf3n del dominio y produce modelos an\xe9micos. En Rails, un modelo ",(0,n.jsx)(a.code,{children:"User"})," con validaciones, callbacks, scopes y l\xf3gica de negocio es idiom\xe1tico y productivo. \xbfEs SRP incompatible con el estilo Active Record? \xbfD\xf3nde est\xe1 el equilibrio?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Hay una tensi\xf3n real. ",(0,n.jsx)(a.strong,{children:"Argumento a favor de DHH"}),": Un modelo ",(0,n.jsx)(a.code,{children:"User"}),' en Rails que contiene validaciones de email, l\xf3gica de autenticaci\xf3n, scopes de b\xfasqueda, y callbacks de notificaci\xf3n es altamente cohesivo en el dominio: todo gira alrededor del concepto "usuario". Separarlo en ',(0,n.jsx)(a.code,{children:"UserValidator"}),", ",(0,n.jsx)(a.code,{children:"UserAuthenticator"}),", ",(0,n.jsx)(a.code,{children:"UserNotifier"}),", ",(0,n.jsx)(a.code,{children:"UserQuery"}),' seg\xfan SRP destruir\xeda la cohesi\xf3n conceptual y crear\xeda 15 archivos donde antes hab\xeda 1, haciendo m\xe1s dif\xedcil entender "qu\xe9 puede hacer un usuario". El framework Active Record intencionalmente integra persistencia y l\xf3gica de dominio. ',(0,n.jsx)(a.strong,{children:"Defensa de SRP"}),": SRP no exige atomizar el modelo de dominio; exige separar responsabilidades que cambian por razones distintas. Un ",(0,n.jsx)(a.code,{children:"User"}),' puede contener l\xf3gica de dominio (validar email) pero no deber\xeda contener l\xf3gica de infraestructura (enviar email via SMTP, escribir en BD). La capa de dominio puede ser cohesiva; lo que SRP separa son responsabilidades de infraestructura y orquestaci\xf3n. El equilibrio: "fat models, skinny services" de Rails es compatible con SRP si el modelo contiene l\xf3gica de dominio pura (reglas de negocio) y delega infraestructura a colaboradores inyectados.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La cr\xedtica de DHH (expuesta en "The Rails Doctrine" y en m\xfaltiples debates con Martin Fowler) apunta a la aplicaci\xf3n dogm\xe1tica de SRP, no al principio en s\xed. Martin Fowler respondi\xf3 que SRP y Active Record no son incompatibles si se entiende que "responsabilidad" no significa "una sola operaci\xf3n" sino "atender a un solo stakeholder".']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"9-cuestionar-puede-srp-llevar-a-una-explosi\xf3n-de-clases-que-empeore-la-mantenibilidad-en-lugar-de-mejorarla-investig\xe1-el-fen\xf3meno-de-ravioli-code-c\xf3digo-ravioli-muchas-clases-peque\xf1as-dif\xedcil-de-seguir-como-contraparte-de-spaghetti-code-d\xf3nde-est\xe1-el-punto-de-equilibrio-seg\xfan-la-literatura",children:'9. [Cuestionar] \xbfPuede SRP llevar a una explosi\xf3n de clases que empeore la mantenibilidad en lugar de mejorarla? Investig\xe1 el fen\xf3meno de "ravioli code" (c\xf3digo ravioli: muchas clases peque\xf1as, dif\xedcil de seguir) como contraparte de "spaghetti code". \xbfD\xf3nde est\xe1 el punto de equilibrio seg\xfan la literatura?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': "Ravioli code" es el t\xe9rmino usado para describir sistemas donde las responsabilidades est\xe1n tan atomizadas que seguir el flujo de ejecuci\xf3n requiere saltar entre 20 archivos. Es la ant\xedtesis del spaghetti code: mientras que spaghetti code tiene todo en una clase, ravioli code tiene cada operaci\xf3n en una clase separada con capas de indirecci\xf3n. SRP mal aplicado produce ravioli. El punto de equilibrio seg\xfan la literatura (Martin Fowler, Robert Martin): (1) ',(0,n.jsx)(a.strong,{children:"Cohesi\xf3n funcional"}),': si dos responsabilidades siempre cambian juntas, no las separes aunque formalmente sean "responsabilidades distintas". CCP tiene prioridad sobre SRP. (2) ',(0,n.jsx)(a.strong,{children:'El "Rule of Three"'}),": no abstraigas hasta que hayas visto el patr\xf3n repetirse al menos tres veces. (3) ",(0,n.jsx)(a.strong,{children:"Tama\xf1o de clase"}),": no es un fin en s\xed mismo. Una clase de 80 l\xedneas con una sola responsabilidad bien definida es mejor que 4 clases de 20 l\xedneas que requieren una coreograf\xeda compleja. (4) ",(0,n.jsx)(a.strong,{children:"Narrativa del c\xf3digo"}),": un nuevo desarrollador deber\xeda poder entender un caso de uso leyendo 3-5 archivos, no 25. Si SRP produce m\xe1s de 5 archivos por caso de uso, probablemente es excesivo."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': El t\xe9rmino "ravioli code" fue popularizado por desarrolladores que observaron que la aplicaci\xf3n dogm\xe1tica de SOLID en Java enterprise produc\xeda sistemas con miles de clases diminutas y f\xe1bricas de f\xe1bricas. Martin respondi\xf3 en Clean Architecture: "SRP no es sobre hacer las clases m\xe1s peque\xf1as; es sobre asegurar que cada clase responda a un solo actor".']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"10-cuestionar-yegor-bugayenko-en-elegant-objects-vol-1-2016-argumenta-que-los-objetos-no-deber\xedan-tener-getters-ni-setters-y-que-la-verdadera-encapsulaci\xf3n-hace-innecesario-srp-es-srp-un-parche-para-la-falta-de-encapsulamiento-real-qu\xe9-pasar\xeda-si-sigui\xe9ramos-los-principios-de-bugayenko-en-lugar-de-solid",children:'10. [Cuestionar] Yegor Bugayenko en "Elegant Objects" (Vol. 1, 2016) argumenta que los objetos no deber\xedan tener getters ni setters, y que la verdadera encapsulaci\xf3n hace innecesario SRP. \xbfEs SRP un parche para la falta de encapsulamiento real? \xbfQu\xe9 pasar\xeda si sigui\xe9ramos los principios de Bugayenko en lugar de SOLID?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Bugayenko sostiene que un objeto verdaderamente encapsulado no expone su estado y solo expone comportamiento. En ese paradigma, el problema que SRP intenta resolver (mezcla de responsabilidades) no ocurre porque: (1) un objeto sin getters no puede ser usado por otros para extraer datos y hacer l\xf3gica externa (evitando Feature Envy); (2) un objeto sin setters es inmutable, eliminando efectos colaterales; (3) la composici\xf3n estricta significa que cada objeto delegar\xeda en colaboradores en lugar de mezclar l\xf3gica. Si se siguieran los principios de Bugayenko en lugar de SOLID: las clases ser\xedan m\xe1s grandes (porque contendr\xedan l\xf3gica de dominio rica) pero con interfaces m\xednimas (sin getters), m\xe1s inmutables (sin setters), y compuestas de otros objetos (no de servicios). El "Employee" de Bugayenko tendr\xeda m\xe9todo ',(0,n.jsx)(a.code,{children:"salary()"})," que internamente calcula, valida y persiste colaborando con objetos compuestos, sin exponer nunca ",(0,n.jsx)(a.code,{children:"getSalary()"})," como double. En este paradigma, SRP no se necesita como principio expl\xedcito porque la encapsulaci\xf3n estricta lo fuerza naturalmente: un objeto solo puede hacer una cosa \u2014 su responsabilidad definida por su interfaz p\xfablica."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Bugayenko es una voz disidente desde dentro de OOP. Su cr\xedtica es que SOLID es una soluci\xf3n a problemas creados por el estilo JavaBeans (objetos pasivos con getters/setters) que no deber\xedan existir en OOP genuina. Si los objetos fueran verdaderamente aut\xf3nomos, no necesitar\xedan que principios externos les digan que no mezclen responsabilidades \u2014 simplemente no podr\xedan."]})]})}function u(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(t,{...e})}):t(e)}},28453(e,a,o){o.d(a,{R:()=>r,x:()=>c});var i=o(96540);const n={},s=i.createContext(n);function r(e){const a=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(s.Provider,{value:a},e.children)}}}]);